#include "FreeRTOS.h"#include "event_groups.h"#include <string>#include <iostream>#include "task.h"#include "queue.h"#include "Structs.h"#include "timers.h"#include "pico/stdlib.h"#include "hardware/timer.h"#include "Task_Control/Control.h"#include "Task_Network/Network.h"#include "Task_UI/UI.h"#include "display/lvgl_port.h"#define EVT_NO_WATER        (1 << 0)#define EVT_WATER_PRESENT  (1 << 1)extern "C" {uint32_t read_runtime_ctr(void) {    return timer_hw->timerawl;}}// lvgl needs timer access so that's a global ptrLVGLPort *g_lvgl_port = nullptr;// timer callbackvoid lvgl_tick_timer_callback(TimerHandle_t xTimer) {    if (g_lvgl_port) {        g_lvgl_port->tick(10);  // 10ms tick    }}EventGroupHandle_t g_water_event_group = nullptr;int main(){    QueueHandle_t to_control;    QueueHandle_t to_UI;    QueueHandle_t to_network;    stdio_init_all();    TimerHandle_t lvgl_timer = xTimerCreate("LVGL_ticks", pdMS_TO_TICKS(10), pdTRUE, NULL, lvgl_tick_timer_callback);    xTimerStart(lvgl_timer, 0);    to_control = xQueueCreate(10, sizeof(Message));    to_UI = xQueueCreate(10, sizeof(Message));    to_network = xQueueCreate(10, sizeof(Message));    g_water_event_group = xEventGroupCreate();    configASSERT(g_water_event_group != nullptr);    //system data sending period is 10 s now for testing    const TickType_t period = pdMS_TO_TICKS(10000);    const TickType_t UI_period = pdMS_TO_TICKS(10);    Control control_task(to_UI,to_network,to_control,period);    UI ui_task(to_UI,to_network,to_control,UI_period);    Network network_task(to_UI,to_network,to_control,period);    vTaskStartScheduler();    return 0;}